BEGIN;
SET LOCAL search_path = public, pg_catalog;

-- CreateTable
CREATE TABLE "seasons" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "slug" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "year" INTEGER NOT NULL,
    "season_number" INTEGER NOT NULL,
    "is_current" BOOLEAN NOT NULL DEFAULT false,

    CONSTRAINT "seasons_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "series" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "season_id" INTEGER NOT NULL,
    "name" TEXT NOT NULL,
    "category" TEXT NOT NULL,
    "linked_to" INTEGER,

    CONSTRAINT "series_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "series_weeks" (
    "series_id" INTEGER NOT NULL,
    "week_number" INTEGER NOT NULL,
    "track_id" INTEGER NOT NULL,
    "track_name" TEXT NOT NULL,
    "race_date" DATE NOT NULL,

    CONSTRAINT "series_weeks_pkey" PRIMARY KEY ("series_id","week_number")
);

-- CreateIndex
CREATE UNIQUE INDEX "seasons_slug_key" ON "seasons"("slug");

-- CreateIndex
CREATE UNIQUE INDEX "seasons_year_season_number_key" ON "seasons"("year", "season_number");

-- CreateIndex
CREATE INDEX "series_season_id_linked_to_idx" ON "series"("season_id", "linked_to");

-- CreateIndex
CREATE UNIQUE INDEX "series_season_id_name_key" ON "series"("season_id", "name");

-- CreateIndex
CREATE UNIQUE INDEX "series_season_id_id_key" ON "series"("season_id", "id");

-- CreateIndex
CREATE INDEX "series_weeks_track_id_idx" ON "series_weeks"("track_id");

-- AddForeignKey
ALTER TABLE "series" ADD CONSTRAINT "series_season_id_fkey" FOREIGN KEY ("season_id") REFERENCES "seasons"("id") ON DELETE RESTRICT ON UPDATE NO ACTION;

-- AddForeignKey
ALTER TABLE "series" ADD CONSTRAINT "series_season_id_linked_to_fkey" FOREIGN KEY ("season_id", "linked_to") REFERENCES "series"("season_id", "id") ON DELETE SET NULL (linked_to) ON UPDATE NO ACTION;

-- AddForeignKey
ALTER TABLE "series_weeks" ADD CONSTRAINT "series_weeks_series_id_fkey" FOREIGN KEY ("series_id") REFERENCES "series"("id") ON DELETE CASCADE ON UPDATE NO ACTION;

-- Custom integrity and access rules are intentionally kept beside Prisma DDL.
ALTER TABLE public.seasons
  ADD CONSTRAINT seasons_slug_nonblank CHECK (btrim(slug) <> ''),
  ADD CONSTRAINT seasons_name_nonblank CHECK (btrim(name) <> ''),
  ADD CONSTRAINT seasons_year_positive CHECK (year > 0),
  ADD CONSTRAINT seasons_number_valid CHECK (season_number BETWEEN 1 AND 4);
CREATE UNIQUE INDEX seasons_one_current ON public.seasons (is_current) WHERE is_current;

ALTER TABLE public.series
  ADD CONSTRAINT series_name_nonblank CHECK (btrim(name) <> ''),
  ADD CONSTRAINT series_category_valid CHECK (category IN ('Formula', 'Sports Car', 'Oval', 'Other')),
  ADD CONSTRAINT series_not_self_linked CHECK (linked_to IS NULL OR linked_to <> id);
ALTER TABLE public.series_weeks
  ADD CONSTRAINT series_weeks_number_positive CHECK (week_number > 0),
  ADD CONSTRAINT series_weeks_track_name_nonblank CHECK (btrim(track_name) <> '');

ALTER TABLE public.seasons ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.series ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.series_weeks ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.seasons, public.series, public.series_weeks FROM PUBLIC, anon, authenticated;
REVOKE ALL ON SEQUENCE public.seasons_id_seq, public.series_id_seq FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.seasons, public.series, public.series_weeks TO anon, authenticated;
CREATE POLICY seasons_public_read ON public.seasons FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY series_public_read ON public.series FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY series_weeks_public_read ON public.series_weeks FOR SELECT TO anon, authenticated USING (true);

COMMIT;
